# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.gaps import find_gaps, gap_labels

OPEN = parse_span("09:00-17:00")

def spans(*texts):
    return [parse_span(text) for text in texts]

class GapTests(unittest.TestCase):
    def test_midday_gap(self):
        worked = spans("09:00-12:00", "13:00-17:00")
        self.assertEqual(
            gap_labels(worked, OPEN),
            ["gap 12:00-13:00 (60 min)"]
        )

    def test_nobody_working(self):
        self.assertEqual(
            gap_labels([], OPEN),
            ["gap 09:00-17:00 (480 min)"]
        )

    def test_full_coverage(self):
        worked = spans("09:00-13:00", "12:00-17:00")
        self.assertEqual(gap_labels(worked, OPEN), [])

    def test_touching_spans_leave_no_gap(self):
        worked = spans("09:00-13:00", "13:00-17:00")
        self.assertEqual(find_gaps(worked, OPEN), [])

    def test_edges_and_unsorted_input(self):
        worked = spans("14:00-15:00", "10:00-12:00")
        self.assertEqual(
            gap_labels(worked, OPEN),
            [
                "gap 09:00-10:00 (60 min)",
                "gap 12:00-14:00 (120 min)",
                "gap 15:00-17:00 (120 min)"
            ]
        )

    def test_before_opening_raises(self):
        with self.assertRaises(ValueError):
            find_gaps(spans("08:00-12:00"), OPEN)

    def test_after_closing_raises(self):
        with self.assertRaises(ValueError):
            find_gaps(spans("16:00-18:00"), OPEN)

if __name__ == "__main__":
    unittest.main()
